INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT156-S4-Q7$batch11$, 156, 4, 7, $batch11$Must Be True$batch11$, $batch11$A truly visual art form—for example, painting—is one in which time plays no essential role. Though it takes time to look at a painting, there is no fixed order in which one must look at its parts, and no fixed amount of time one must spend examining it. In contrast, most art forms, such as poetry and music, are essentially temporal; that is, they require performance, which means they must be experienced in a fixed order and over a roughly fixed amount of time. Poetry, for instance, though often written down and thus seemingly a visual art, actually must be performed, even if the performance is only a silent reading to oneself.$batch11$, $batch11$If the statements above are true, then on the basis of them which one of the following must be true?$batch11$, $batch11$A$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q7$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$Truly visual art forms do not essentially involve performance.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$Poetry is less like music than it is like painting.$batch11$, $batch11$Opposite$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$Spatiality and temporality are mutually exclusive components of art forms.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$Art forms that must be examined for an extended period of time in order to be understood are essentially temporal.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$Anything capable of being performed is either musical or poetic, or both musical and poetic.$batch11$, $batch11$Too Strong$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$In a truly visual art form, like painting, time plays no essential role. Temporal art forms require performance, which means a fixed order and a roughly fixed amount of time. Poetry looks visual but must be performed.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Performance → fixed order and time → time plays an essential role. Truly visual art has no essential role for time. Take the contrapositive: truly visual art doesn't essentially involve performance.$batch11$), (2, $batch11$Goal$batch11$, $batch11$Truly visual art forms don't essentially involve performance.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT156-S4-Q7$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Performance requires fixed time, and visual art has no essential role for time. So visual art doesn't require performance.$batch11$), ($batch11$B$batch11$, $batch11$Poetry is temporal and performed, like music, not visual like painting.$batch11$), ($batch11$C$batch11$, $batch11$Spatiality never comes up, and nothing says the two can't coexist.$batch11$), ($batch11$D$batch11$, $batch11$Temporal art needs a fixed order and time. A painting might need long study with no fixed order at all.$batch11$), ($batch11$E$batch11$, $batch11$Poetry and music are examples of temporal art. Nothing says they are the only performed arts.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT156-S4-Q7$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
